from pathlib import Path
import base64,json,zlib,sys
p=Path(sys.argv[1] if len(sys.argv)>1 else 'site/index.html')
s=p.read_text(encoding='utf-8')
blob=''
data=json.loads(zlib.decompress(base64.b64decode(blob)).decode())
if '</style>' not in s: raise SystemExit('classic patch: style marker missing')
s=s.replace('</style>',data['css']+'\n</style>',1)
anchor='async function boot()'; pos=s.find(anchor)
if pos<0: raise SystemExit('classic patch: boot marker missing')
s=s[:pos]+data['js']+'\n'+s[pos:]
for marker in ['Стартовый цикл','Добавить новую сделку','openTesterAdmin','openSupportAdmin','compact-scroll','Mini App Beta 0.8']:
    if marker not in s: raise SystemExit('classic patch validation missing: '+marker)
p.write_text(s,encoding='utf-8')
print('Classic PlanFact UI patch applied')
